// components/LogoShowcase.jsx
import React from "react";
import styled from "styled-components";
import { LOGOS } from "../../Utils/Constants";
import { useTranslation } from "react-i18next";

// Swiper
import { Swiper, SwiperSlide } from "swiper/react";
import { Navigation, Autoplay } from "swiper/modules";
import "swiper/css";
import "swiper/css/navigation";

const Section = styled.section`
    width: 100%;
    padding: clamp(20px, 3vw, 56px) 0;
    color: #354358;
`;

const Container = styled.div`
    width: 100%;
    padding-inline: clamp(12px, 4vw, 48px);
    margin: 0 auto;
`;

const Title = styled.h2`
    margin: 0 0 1.5rem 0;
    text-align: center;
`;

const Card = styled.div`
    border-radius: 12px;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    margin: 10px;
    &:hover {
        transform: translateY(-2px);
        box-shadow: 0 10px 26px rgba(0,0,0,.10);
        border-color: rgba(0,0,0,.12);
    }
`;

const LogoBox = styled.figure`
    margin: 0;
    aspect-ratio: 4 / 3;
    display: grid;
    place-items: center;

    img {
        width: 70%;
        max-height: 60%;
        object-fit: contain;
    }
`;

const Brand = styled.figcaption`
    display: grid;
    place-items: center;
    text-align: center;
    padding: 6px 8px 8px;
`;

// Переопределяем стили Swiper стрелок + фикс направления
const SwiperWrapper = styled.div`
    .swiper { direction: ltr; } /* важный фикс: не наследовать rtl */
    .swiper-button-next,
    .swiper-button-prev {
        color: #33beb3 !important;
    }
    .swiper-button-next::after,
    .swiper-button-prev::after {
        font-size: 25px;
        font-weight: bold;
    }
`;

export default function LogoShowcase() {
    const { t } = useTranslation();

    return (
        <Section aria-labelledby="logo-showcase-title">
            <Container>
                <Title id="logo-showcase-title">{t("logos.title")}</Title>

                <SwiperWrapper>
                    <Swiper
                        dir="ltr"                                 // ← фикс
                        modules={[Navigation, Autoplay]}
                        spaceBetween={16}
                        slidesPerView={5}
                        loop
                        navigation
                        autoplay={{ delay: 2500, disableOnInteraction: false }}
                        breakpoints={{
                            320:  { slidesPerView: 2 },
                            520:  { slidesPerView: 3 },
                            768:  { slidesPerView: 4 },
                            1024: { slidesPerView: 5 },
                        }}
                    >
                        {LOGOS.map((item) => (
                            <SwiperSlide key={item.brand}>
                                <Card>
                                    <LogoBox>
                                        <img src={item.src} alt={item.alt} loading="lazy" decoding="async" />
                                    </LogoBox>
                                    <Brand>{item.brand}</Brand>
                                </Card>
                            </SwiperSlide>
                        ))}
                    </Swiper>
                </SwiperWrapper>
            </Container>
        </Section>
    );
}
