import React, {useEffect} from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";

const Card = styled.article`
    display: flex;
    flex-direction: column;
    margin: 20px; 
    flex: 1 1 auto;   /* занять всю высоту slide-inner */
    background: transparent;
    min-height: 0;
    gap: 16px;
    border-radius: 18px;
    padding: 22px 18px;

color: ${({ theme }) => theme.colors?.text ?? "#354358"};
 box-shadow: ${({ $featured, $dir }) =>
    $featured
        ? `${$dir === "rtl" ? "-20px" : "20px"} 20px 20px rgba(0,0,0,.25)`
        : "none"};
transition: border-color 0.2s ease,
box-shadow .2s ease;
`;

const Header = styled.header`
    display: grid;
    gap: 6px;
`;

const PlanName = styled.h3`
    font-weight: bold;
    margin: 0;
    color: ${({ theme }) => theme.colors?.heading ?? "#354358"};
`;

const Tagline = styled.p`
    margin: 12px 0;
    color: ${({ theme }) => theme.colors?.muted ?? "#354358"};
    font-size: 2.5vh;
    line-height: 1.5;
    padding: 12px;
    border: 1px solid ${({ theme }) => theme.colors?.heading ?? "#33beb3"};
    border-radius: 15px;
`;

const PriceWrap = styled.div`
    display: grid;
    gap: 6px;
    margin-top: 6px;
`;

const MainPrice = styled.div`
    font-size: 4vh;
    font-weight: 900;
    color: ${({ theme }) => theme.colors?.heading ?? "#33beb3"};
`;

const PromoBadge = styled.span`
    justify-self: start;
    font-size: 16px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    padding: 6px 20px;
    border-radius: 999px;
    background: ${({ theme }) => theme.colors?.badge ?? "#354358"};
    color: ${({ theme }) => theme.colors?.badgeText ?? "white"};
`;

const Row = styled.div`
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
`;

const PromoPrice = styled.div`
    font-size: 28px;
    font-weight: 900;
    color: ${({ theme }) => theme.colors?.accent ?? "#33beb3"};
`;

const OldPrice = styled.div`
    font-size: 20px;
    color: ${({ theme }) => theme.colors?.muted2 ?? "#33beb3"};
    text-decoration: line-through;
`;

const SmallMuted = styled.div`
    font-size: 16px;
    font-weight: bold;
    color: ${({ theme }) => theme.colors?.muted ?? "#354358"};
`;

const Block = styled.section`
    padding-top: 12px;
`;

const BlockTitle = styled.h4`
    font-size: 2vh;
    font-weight: 800;
    text-align: start;
    letter-spacing: .2px;
    text-transform: uppercase;
    padding: 0;
    color: ${({ theme }) => theme.colors?.title ?? "#354358"};
`;

const List = styled.ul`
    margin: 0;
    text-align: start;
    padding-inline-start: 18px;
    color: ${({ theme }) => theme.colors?.list ?? "#354358"};
    line-height: 1.5;
    li + li { margin-top: 2px; }
`;

const CTAGroup = styled.div`
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
    margin-top: auto;   /* прижимаем кнопки к низу, выравнивая высоту */
    @media (min-width: 420px) {
        grid-template-columns: 1fr 1fr;
    }
`;

const PrimaryButton = styled.a`
    display: inline-grid;
    place-items: center;
    height: 42px;
    background: ${({ theme }) => theme.colors?.accent ?? "#33beb3"};
    color: ${({ theme }) => theme.colors?.accentOn ?? "#fff"};
    font-weight: 800;
    text-decoration: none;
    text-wrap: nowrap;
    padding: 5px 20px;
    transition: filter .15s ease;
    &:hover {
        background: ${({ theme }) => theme.colors?.accent ?? "#354358"};
        color: ${({ theme }) => theme.colors?.accentOn ?? "#fff"}!important;
    }
`;

const GhostButton = styled.a`
    display: inline-grid;
    place-items: center;
    height: 42px;
    border: 1.5px solid ${({ theme }) => theme.colors?.ghostBorder ?? "#354358"};
    background: transparent;
    font-weight: bold;
    color: ${({ theme }) => theme.colors?.ghostText ?? "#354358"};
    text-decoration: none;
    transition: background-color .15s ease;
    text-wrap: nowrap;
    padding: 5px 20px;
    &:hover {
        color: ${({ theme }) => theme.colors?.ghostHover ?? "#33beb3"};
        border-color: ${({ theme }) => theme.colors?.ghostHover ?? "#33beb3"};
    }
`;

/* ---------- helpers ---------- */
const formatILS = (n) =>
    typeof n === "number"
        ? n.toLocaleString("he-IL", { style: "currency", currency: "ILS", maximumFractionDigits: 0 })
        : n;

const formatDate = (iso) => {
    try {
        const d = new Date(iso);
        const dd = String(d.getDate()).padStart(2, "0");
        const mm = String(d.getMonth() + 1).padStart(2, "0");
        const yyyy = d.getFullYear();
        return `${dd}.${mm}.${yyyy}`;
    } catch {
        return iso;
    }
};

// акция активна, если есть цена и (нет until ИЛИ текущая дата <= until 23:59:59)
const isPromoActive = (promo) => {
    if (!promo?.price) return false;
    if (!promo?.until) return true;
    const [y, m, d] = promo.until.split("-").map(Number);
    const until = new Date(y, m - 1, d, 23, 59, 59, 999);
    return Date.now() <= until.getTime();
};

function PricingCart({
                         name,
                         tagline,
                         price,
                         promo,
                         promoLabel,
                         promoPrice,
                         promoUntil,
                         features = [],
                         addonsTitle,
                         addons = [],
                         excludesTitle,
                         excludes = [],
                         featured = false,
                         whatsappHref = "https://wa.me/972547615507",
                         emailHref = "mailto:hexobee.dev@gmail.com",
                         whatsappText,
                         emailText,
                         dir,
                     }) {
    const { t } = useTranslation();

    const promoObj = promo ?? { label: promoLabel, price: promoPrice, until: promoUntil };
    const promoOk = isPromoActive(promoObj);

    const _price = typeof price === "number" ? formatILS(price) : price;
    const _promo = typeof promoObj?.price === "number" ? formatILS(promoObj.price) : promoObj?.price;

    return (
        <Card $featured={featured} $dir={dir}>
            <Header>
                <PlanName>{name}</PlanName>
                {tagline ? <Tagline>{tagline}</Tagline> : null}
            </Header>

            {/* price */}
            <PriceWrap>
                {promoOk ? (
                    <>
                        {promoObj?.label ? <PromoBadge>{promoObj.label}</PromoBadge> : null}
                        <Row>
                            <PromoPrice>{_promo}</PromoPrice>
                            <OldPrice>{_price}</OldPrice>
                        </Row>
                        {promoObj?.until ? <SmallMuted>{t("pricing.promoUntilPrefix", "до")} {formatDate(promoObj.until)}</SmallMuted> : null}
                    </>
                ) : (
                    <MainPrice>{_price}</MainPrice>
                )}
            </PriceWrap>

            {/* lists */}
            {features?.length > 0 && (
                <Block>
                    <BlockTitle>{t("pricing.includedTitle", "Что входит")}</BlockTitle>
                    <List>{features.map((x, i) => <li key={`f-${i}`}>{x}</li>)}</List>
                </Block>
            )}

            {addons?.length > 0 && (
                <Block>
                    <BlockTitle>{addonsTitle || t("pricing.addonsTitle", "Дополнительно")}</BlockTitle>
                    <List>{addons.map((x, i) => <li key={`a-${i}`}>{x}</li>)}</List>
                </Block>
            )}

            {excludes?.length > 0 && (
                <Block>
                    <BlockTitle>{excludesTitle || t("pricing.excludesTitle", "Не входит")}</BlockTitle>
                    <List>{excludes.map((x, i) => <li key={`e-${i}`}>{x}</li>)}</List>
                </Block>
            )}

            {/* CTA */}
            <CTAGroup>
                <PrimaryButton href={whatsappHref} target="_blank" rel="noreferrer" aria-label={whatsappText || t("pricing.cta.whatsapp")}>
                    {whatsappText || t("pricing.cta.whatsapp")}
                </PrimaryButton>
                <GhostButton href={emailHref}>
                    {emailText || t("pricing.cta.email")}
                </GhostButton>
            </CTAGroup>
        </Card>
    );
}

export default React.memo(PricingCart);

