// RightNav.js
import React, { useEffect, useState } from 'react';
import styled from 'styled-components';
import { useLocation } from 'react-router-dom';
import { LOGO_BLUE, LOGO_WHITE } from '../../Utils/Constants';
import { faChevronDown, faGlobe } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { useTranslation } from 'react-i18next';

const RightNavWrapper = styled.div`
    width: 100vw;
    height: 12vh;
    padding: 0 3vw;
    display: flex;
    align-items: center;
    justify-content: center;
`;

const UL = styled.ul`
    list-style: none;
    height: 12vh;
    margin: 0;
    padding: 0;
    display: flex;
    width: 100vw;
    align-items: center;
    justify-content: space-between;
    letter-spacing: 2px;
    font-weight: bold;
    font-size: 1.8vw;
    flex-flow: row nowrap;

    @media (max-width: 978px) {
        position: fixed;
        flex-direction: column;
        justify-content: start;
        background-color: #f8f8f8;
        top: 0;
        right: 0;
        height: 100vh;
        width: 100vw;
        padding: 5vh 2vw;
        display: ${({ $open }) => ($open ? 'flex' : 'none')};
        overflow-y: auto;
    }
`;

const LogoLink = styled.a`
    text-decoration: none;
`;

const Logo = styled.img`
    width: 8vw;
    @media (max-width: 978px) {
        width: 15vh;
        margin-bottom: 3vh;
    }
`;

const NabBar = styled.nav`
    display: flex;
    align-items: center;
    gap: 2vw;

    a {
        color: ${({ $colornav }) => $colornav};
        text-decoration: none;
        font-size: 1.6vw;
        transition: transform 0.3s ease;

        &:hover {
            transform: scale(1.2);
        }

        &:active {
            color: #33beb3;
        }

        @media (max-width: 978px) {
            font-size: 3.5vh;
            color: #354358;
        }
    }

    @media (max-width: 978px) {
        flex-direction: column;
        align-items: center;
        justify-content: start;
        gap: 1.5vh;
        margin-top: 3vh;
    }
`;

const Tel = styled.div`
    direction: ltr;
    color: ${({ $colornav }) => $colornav};
    font-weight: bold;
    font-size: 1.6vw;
    @media (max-width: 978px) {
        font-size: 3.5vh;
        color: #33beb3;
        margin: 2vh 0;
    }
`;

const Dropdown = styled.div`
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    margin-inline-start: 2vw;
    
    svg {
        margin:0 0.5vw;
    }

    button {
        background: none;
        border: none;
        cursor: pointer;
        color: ${({ $colornav }) => $colornav};
        display: flex;
        align-items: center;
        width: 100%;
        
        p{
            font-size: 1.6vw;
            margin: 0 0.3vw;
            font-weight: bolder;
            letter-spacing: 2px;
        }
        
        @media (max-width: 978px) {
            color: #33beb3;
            font-size: 3.5vh;
            margin-top: 6vh;
            font-weight: bolder;

            p{
                font-size: 3.5vh;
            }
        }
        @media (max-width: 978px) {
            svg {
                margin: 0 2vw;
            }
        }
    }

    div {
        position: absolute;
        top: 100%;
        left: auto;
        width: 100%;
        background: #f8f8f8;
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
        display: ${({ $show }) => ($show ? 'flex' : 'none')};
        flex-direction: column;
        padding: 1vh;

        p {
            cursor: pointer;
            font-size: 1.4vw;
            color: #354358;
            margin: 0;
            padding: 5px 20px;
            letter-spacing: 2px;
            
            &:hover {
                color: #33beb3;
            }

            @media (max-width: 978px) {
                font-size: 3.5vh;
            }
        }
        @media (max-width: 978px) {
            width: fit-content;
            
        }
    }
`;

const RightNav = (props) => {
    const { t, i18n } = useTranslation();
    const [colorNav, setColorNav] = useState('#33beb3');
    const [isShowDropDown, setShowDropDown] = useState(false);
    const [address, setAddress] = useState('/survey-form-eng');
    const location = useLocation();

    useEffect(() => {
        setColorNav(props.scroll ? 'white' : '#354358');
    }, [props.scroll, location]);

    const handleClickSurvey = () => {
        const lang = props.currentLang;
        setAddress(
            lang === 'ru' ? '/survey-form-ru' :
                lang === 'he' || lang === 'iw' ? '/survey-form-he' :
                    '/survey-form-eng'
        );
    };

    const changeLanguage = (lng) => {
        i18n.changeLanguage(lng);
        props.changeLanguage(lng);
        setShowDropDown(false);
        props.setOpen(false);
    };

    return (
        <RightNavWrapper>
            <UL $open={props.open}>
                <LogoLink href="#home" onClick={() => props.setOpen(false)}>
                    <Logo src={(props.scroll === false || window.innerWidth < 978) ? LOGO_BLUE : LOGO_WHITE} alt="logo" />
                </LogoLink>

                <Tel $colornav={colorNav}>+(972)54-761-55-07</Tel>

                <NabBar $colornav={colorNav}  onClick={() => props.setOpen(false)}>
                    <a href="/">{t('header.nav.home')}</a>
                    <a href="#portfolio">{t('header.nav.portfolio')}</a>
                    <a href="#about">{t('header.nav.about_us')}</a>
                    <a href="#contact">{t('header.nav.contact')}</a>
                    <a onClick={handleClickSurvey} href={address} target="_blank" rel="noopener noreferrer">
                        {t('header.nav.survey')}
                    </a>
                </NabBar>

                <Dropdown $colornav={colorNav} $show={isShowDropDown}>
                    <button onClick={() => setShowDropDown(!isShowDropDown)}>
                        <FontAwesomeIcon icon={faGlobe} />
                        <p>{t('header.nav.lang')}</p>
                        <FontAwesomeIcon icon={faChevronDown} />
                    </button>
                    <div>
                        {t('header.languages', { returnObjects: true }).map((v) => (
                            <p key={v.code} onClick={() => changeLanguage(v.code)}>{v.nativeName}</p>
                        ))}
                    </div>
                </Dropdown>
            </UL>
        </RightNavWrapper>
    );
};

export default RightNav;
